import tkinter as tk
from tkinter import filedialog, font
from tkinter.scrolledtext import ScrolledText
from PIL import Image, ImageTk, ImageEnhance
import keyboard
from pynput.keyboard import Controller, Key
from threading import Lock, Thread
import time
import re
import random
import os
import base64
from io import BytesIO

# Embedded background image
BACKGROUND_IMAGE = """')"""

class KeyboardSimulatorApp:
    def __init__(self, master):
        self.master = master
        self.master.title("PPiano 1.0.0")
        self.master.geometry("600x400")
        self.master.resizable(False, False)

        self.setup_background()
        self.create_widgets()
        self.setup_text_tags()

        self.monitoring_thread = None
        self.text_set = []
        self.set_index = 0
        self.keyboard_controller = Controller()
        self.lock = Lock()
        self.current_element = None
        self.running = False
        self.imperfect_mode = False
        self.file_selection_mode = False
        
        self.visible_lines = 1

    def setup_background(self):
        # Decode the base64 image (purple background)
        image_data = base64.b64decode(BACKGROUND_IMAGE)
        bg_image = Image.open(BytesIO(image_data))
        bg_image = bg_image.resize((600, 400), Image.LANCZOS)
        
        # Create a semi-transparent overlay
        overlay = Image.new('RGBA', bg_image.size, (0, 0, 0, 128))
        bg_image = Image.alpha_composite(bg_image.convert('RGBA'), overlay)
        
        self.bg_photo = ImageTk.PhotoImage(bg_image)

        # Create a canvas and put the image on it
        self.canvas = tk.Canvas(self.master, width=600, height=400)
        self.canvas.pack(fill="both", expand=True)
        self.canvas.create_image(0, 0, image=self.bg_photo, anchor="nw")

    def create_widgets(self):
        # Custom font
        custom_font = font.Font(family="Roboto", size=10, weight="bold")

        # Text display (moved down)
        self.text_display = ScrolledText(self.master, wrap=tk.WORD, width=50, height=10, 
                                         font=custom_font, fg="white", bg="#1a1a1a")
        self.text_display.place(relx=0.5, rely=0.4, anchor="center")
        #self.text_display.config(state=tk.DISABLED) 

        self.file_list = tk.Listbox(self.master, font=custom_font, fg="white", bg="#1a1a1a")
        self.file_list.place(relx=0.5, rely=0.4, anchor="center")
        self.file_list.bind('<Double-1>', self.on_file_select)
        self.file_list.bind('<Return>', self.on_file_select)
        self.file_list.place_forget()  # Initially hidden

        self.toggle_button = tk.Button(self.master, text="📁", command=self.toggle_file_selection,
                                       font=custom_font, fg="white", bg="#333333", width=3, height=2)
        self.toggle_button.place(relx=0.9, rely=0.4, anchor="center")

        # Frame for buttons and checkboxes with rounded corners
        control_frame = tk.Frame(self.master, bg="#1a1a1a")
        control_frame.place(relx=0.5, rely=0.8, anchor="center")

        # Function to create rounded buttons
        def create_rounded_button(parent, text, command):
            return tk.Button(parent, text=text, command=command, font=custom_font,
                             fg="white", bg="#333333", bd=0, highlightthickness=0,
                             relief="flat", padx=10, pady=5,
                             activebackground="#444444", activeforeground="white")

        # File loading button
        self.load_button = create_rounded_button(control_frame, "Load File", self.load_file)
        self.load_button.grid(row=0, column=0, padx=5, pady=5)

        # Always on top toggle
        self.always_on_top = tk.BooleanVar()
        self.always_on_top_check = tk.Checkbutton(control_frame, text="Pin Window", variable=self.always_on_top,
                                                  command=self.toggle_always_on_top, font=custom_font,
                                                  fg="white", bg="#1a1a1a", selectcolor="#555555",
                                                  activebackground="#1a1a1a", activeforeground="white")
        self.always_on_top_check.grid(row=0, column=1, padx=5, pady=5)

        # Imperfect mode toggle
        self.imperfect_mode_var = tk.BooleanVar()
        self.imperfect_mode_check = tk.Checkbutton(control_frame, text="Imperfect Mode", variable=self.imperfect_mode_var,
                                                   command=self.toggle_imperfect_mode, font=custom_font,
                                                   fg="white", bg="#1a1a1a", selectcolor="#555555",
                                                   activebackground="#1a1a1a", activeforeground="white")
        self.imperfect_mode_check.grid(row=0, column=2, padx=5, pady=5)

        # Status label
        self.status_label = tk.Label(control_frame, text="Press '-' to produce a note",
                                     font=custom_font, fg="white", bg="#1a1a1a")
        self.status_label.grid(row=1, column=0, columnspan=3, pady=5)

    # Switchable file selection, from Windows Explorer and own application
    def toggle_file_selection(self):
        self.file_selection_mode = not self.file_selection_mode
        if self.file_selection_mode:
            self.text_display.place_forget()
            self.file_list.place(relx=0.5, rely=0.4, anchor="center")
            self.load_txt_files()
        else:
            self.file_list.place_forget()
            self.text_display.place(relx=0.5, rely=0.4, anchor="center")

    # Shows text files at current folder
    def load_txt_files(self):
        self.file_list.delete(0, tk.END)
        for file in os.listdir('.'):
            if file.endswith('.txt'):
                self.file_list.insert(tk.END, file)

    #Selecting the file
    def on_file_select(self, event):
        selection = self.file_list.curselection()
        if selection:
            filename = self.file_list.get(selection[0])
            self.load_file_content(filename)
            self.toggle_file_selection()
    
    #Loads its content
    def load_file_content(self, filename):
        with open(filename, 'r', encoding='utf-8') as file:
            content = file.read()
        self.reset_simulator(content)

    #Resets to beginning of the sheet
    def reset_simulator(self, content):
        self.text_display.config(state=tk.NORMAL)
        self.text_display.delete(1.0, tk.END)
        self.text_display.insert(tk.END, content)
        self.text_display.config(state=tk.DISABLED)
        self.text_set = self.parse_text_to_set(content)
        self.set_index = 0
        self.highlight_current_element()
        self.start_monitoring()

    # Purple text highlight
    def setup_text_tags(self):
        self.text_display.tag_configure("highlight", background="purple")
        
    # Windows load file
    def load_file(self):
        filename = filedialog.askopenfilename(filetypes=[("Text files", "*.txt")])
        if filename:
            self.load_file_content(filename)

    # Updates the text display
    def update_text_display(self, content):
        self.text_display.config(state=tk.NORMAL)
        self.text_display.delete(1.0, tk.END)
        self.text_display.insert(tk.END, content)
        self.text_display.config(state=tk.DISABLED)

    #Highlights the current note
    def highlight_current_element(self):
        self.text_display.tag_remove("highlight", "1.0", tk.END)
        if self.set_index < len(self.text_set):
            element, start_index = self.text_set[self.set_index]
            end_index = start_index + len(element)
            start = self.text_display.index(f"1.0 + {start_index} chars")
            end = self.text_display.index(f"1.0 + {end_index} chars")
            self.text_display.tag_add("highlight", start, end)
            
            # Get the line number of the current element
            current_line = int(float(start))
            
            # Calculate the first visible line
            first_visible = self.text_display.index("@0,0")
            first_visible_line = int(float(first_visible))
            
            # If the current line is the last visible line or beyond, scroll
            if current_line >= first_visible_line + self.visible_lines - 1:
                # Scroll to make the current line the top line
                self.text_display.see(f"{current_line+0}.0")
                self.text_display.yview_moveto(1.0)  # Scroll to the bottom
                self.text_display.see(f"{current_line+0}.0")

                self.text_display.update()

    def toggle_always_on_top(self):
        self.master.attributes('-topmost', self.always_on_top.get())

    def toggle_imperfect_mode(self):
        self.imperfect_mode = self.imperfect_mode_var.get()

    #Formats text into a set for the application
    def parse_text_to_set(self, text):
        elements = []
        index = 0
        pattern = r'\[([^\]]+)\]|(\S)'
        for match in re.finditer(pattern, text):
            if match.group(1):  # Matched a group in brackets
                elements.append((match.group(1), match.start() + 1))  # +1 to skip the opening bracket
            elif match.group(2) and match.group(2) != '|' and match.group(2) != ','  and match.group(2) != '.' and match.group(2) != '-' and match.group(2) != '{' and match.group(2) != '}'and match.group(2) != '<' and match.group(2) != '>':  # Matched a single character, not '|'
                elements.append((match.group(2), match.start()))
            index = match.end()
        return elements
    
    # Simulates keypress when pressed
    def simulate_keypress(self, key, press=True, release=False):
        # If a note has special characters, enables shift
        shift_keys = {'!': '1', '@': '2', '$': '4', '%': '5', '^': '6', '&': '7', '*': '8', '(': '9'}
        
        if key in shift_keys:
            with self.keyboard_controller.pressed(Key.shift):
                if press:
                    self.keyboard_controller.press(shift_keys[key])
                if release:
                    self.keyboard_controller.release(shift_keys[key])
        elif key.isupper():
            with self.keyboard_controller.pressed(Key.shift):
                if press:
                    self.keyboard_controller.press(key.lower())
                if release:
                    self.keyboard_controller.release(key.lower())
        else:
            if press:
                self.keyboard_controller.press(key)
            if release:
                self.keyboard_controller.release(key)

    #Imperfect mode generating mistakes
    def generate_random_char(self):
        forbidden_chars = set([',', '-', '+','\\','´',';','ç','[',']','{','}','`','~','/','\'','_','|','=','<','>',':','\"','?','.'])
        while True:
            new_char = chr(random.randint(33, 126))
            if new_char not in forbidden_chars:
                return new_char

    #Imperfect mode - Changes a note for the generated wrong one
    def introduce_error(self, element):
        if len(element) > 1:
            if random.random() < 0.05:
                index = random.randint(0, len(element) - 1)
                new_char = self.generate_random_char()
                return element[:index] + new_char + element[index+1:]
        else:
            if random.random() < 0.05:
                return self.generate_random_char()
        return element

    # Progresses the sheet
    def process_next(self):
        with self.lock:
            if self.set_index < len(self.text_set):
                self.current_element, _ = self.text_set[self.set_index]
                if self.imperfect_mode:
                    self.current_element = self.introduce_error(self.current_element)
                self.set_index += 1
                self.highlight_current_element()
                return True
            return False

    # Wait for key input
    def key_monitoring_thread(self):
        minus_pressed = False
        while self.running:
            if keyboard.is_pressed('-'):
                if not minus_pressed:
                    minus_pressed = True
                    if self.process_next() and self.current_element:
                        for char in self.current_element:
                            self.simulate_keypress(char, press=True, release=False)
                            time.sleep(0.0)  # Small delay between keypresses
            else:
                if minus_pressed:
                    minus_pressed = False
                    if self.current_element:
                        for key in self.current_element:
                            self.simulate_keypress(key, press=False, release=True)
                    self.current_element = None

            if keyboard.is_pressed(','):
                self.reset_scroll()
            
            time.sleep(0.01)

    # Resets scroll to the top when pressed to reset
    def reset_scroll(self):
        self.set_index = 0
        self.highlight_current_element()
        self.text_display.see("1.0")  # Scroll to the top
        self.text_display.update()


    def start_monitoring(self):
        if not self.running:
            self.running = True
            self.monitoring_thread = Thread(target=self.key_monitoring_thread)
            self.monitoring_thread.start()

    def stop_monitoring(self):
        self.running = False
        if self.monitoring_thread:
            self.monitoring_thread.join()

    def on_closing(self):
        self.stop_monitoring()
        self.master.destroy()

if __name__ == "__main__":
    root = tk.Tk()
    app = KeyboardSimulatorApp(root)
    root.protocol("WM_DELETE_WINDOW", app.on_closing)
    root.mainloop()